window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8a10aa7cdf2368f7"]={"versions": [{"id": "FIG-8a10aa7cdf2368f7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur formalen ECU-Konfigurationsbeschreibung (ECUC-Parameterdefinition) im AUTOSAR-Basissoftware-Modul Diagnostic Event Manager (<code>Dem</code>). Das Diagramm spezifiziert die Metamodell-Struktur für die Konfiguration benutzerspezifischer Callbacks bei Statusänderungen diagnostischer Events (<code>EventStatusChanged</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Konfigurationselemente und deren hierarchische Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>DemEventParameter</code> (<code>: EcucParamConfContainerDef</code>): Übergeordneter Konfigurationscontainer für diagnostische Ereignisse mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 65535</code>.</li>\n<li><code>DemCallbackEventStatusChanged</code> (<code>: EcucParamConfContainerDef</code>): Sub-Container (Rolle <code>+subContainer</code>), der per Komposition in <code>DemEventParameter</code> eingebettet ist. Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> (beliebig viele Callbacks konfigurierbar). Gekennzeichnet mit dem Änderungsmarker <code>A</code>.</li>\n<li><code>DemCallbackEventStatusChangedFnc</code> (<code>: EcucFunctionNameDef</code>): Konfigurationsparameter (Rolle <code>+parameter</code>), der per Komposition im Container <code>DemCallbackEventStatusChanged</code> enthalten ist. Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>. Definiert den C-Funktionsnamen des aufzurufenden Callbacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Konfigurationsstruktur ohne Laufzeitsequenzen. Bei Eintreten einer Statusänderung eines <code>DemEventParameter</code> (z. B. UDI-Bits oder Event-Statusübergänge gemäß AUTOSAR-Dem-Spezifikation) iteriert das Dem-Modul über alle konfigurierten <code>DemCallbackEventStatusChanged</code>-Instanzen und ruft die jeweils über <code>DemCallbackEventStatusChangedFnc</code> hinterlegte C-Callback-Funktion mit den entsprechenden Statusparametern auf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Parameterdefinition für BSW-Konfiguratoren und Dem-Code-Generatoren. Pro diagnostischem Event (<code>DemEventParameter</code>) können null bis beliebig viele Callback-Container angelegt werden. Jeder Callback-Container darf maximal einen Funktionsnamen (<code>EcucFunctionNameDef</code>) bereitstellen; ist dieser konfiguriert, muss die Zielfunktion der standardisierten C-Signatur für <code>DemCallbackEventStatusChanged</code> entsprechen und im Linklauf auflösbar sein.</p>"}, {"id": "FIG-86ee5a292cc1a033", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur formalen ECU-Konfigurationsbeschreibung (ECUC-Parameterdefinition) im AUTOSAR-Basissoftware-Modul Diagnostic Event Manager (<code>Dem</code>). Das Diagramm spezifiziert die Metamodell-Struktur für die Konfiguration benutzerspezifischer Callbacks bei Statusänderungen diagnostischer Events (<code>EventStatusChanged</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Konfigurationselemente und deren hierarchische Kompositionsbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>DemEventParameter</code> (<code>: EcucParamConfContainerDef</code>): Übergeordneter Konfigurationscontainer für diagnostische Ereignisse mit <code>lowerMultiplicity = 1</code> und <code>upperMultiplicity = 65535</code>.</li>\n<li><code>DemCallbackEventStatusChanged</code> (<code>: EcucParamConfContainerDef</code>): Sub-Container (Rolle <code>+subContainer</code>), der per Komposition in <code>DemEventParameter</code> eingebettet ist. Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> (beliebig viele Callbacks konfigurierbar). Gekennzeichnet mit dem Änderungsmarker <code>A</code>.</li>\n<li><code>DemCallbackEventStatusChangedFnc</code> (<code>: EcucFunctionNameDef</code>): Konfigurationsparameter (Rolle <code>+parameter</code>), der per Komposition im Container <code>DemCallbackEventStatusChanged</code> enthalten ist. Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>. Definiert den C-Funktionsnamen des aufzurufenden Callbacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Konfigurationsstruktur ohne Laufzeitsequenzen. Bei Eintreten einer Statusänderung eines <code>DemEventParameter</code> (z. B. UDI-Bits oder Event-Statusübergänge gemäß AUTOSAR-Dem-Spezifikation) iteriert das Dem-Modul über alle konfigurierten <code>DemCallbackEventStatusChanged</code>-Instanzen und ruft die jeweils über <code>DemCallbackEventStatusChangedFnc</code> hinterlegte C-Callback-Funktion mit den entsprechenden Statusparametern auf.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Parameterdefinition für BSW-Konfiguratoren und Dem-Code-Generatoren. Pro diagnostischem Event (<code>DemEventParameter</code>) können null bis beliebig viele Callback-Container angelegt werden. Jeder Callback-Container darf maximal einen Funktionsnamen (<code>EcucFunctionNameDef</code>) bereitstellen; ist dieser konfiguriert, muss die Zielfunktion der standardisierten C-Signatur für <code>DemCallbackEventStatusChanged</code> entsprechen und im Linklauf auflösbar sein.</p>"}], "trans": [{"from": "FIG-8a10aa7cdf2368f7", "to": "FIG-86ee5a292cc1a033", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
